#!/usr/bin/env python3
"""Embed the subset UI fonts as C++ byte arrays.

Run from anywhere:

    python third_party/fonts/embed_fonts.py

The generated files are committed so a normal build needs neither Python nor
fonttools. Regenerate the subset TTFs first with third_party/fonts/subset.sh if
the source fonts change.
"""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
FONT_DIR = ROOT / "third_party" / "fonts"
OUT_CPP = ROOT / "src" / "ui" / "embedded_fonts.cpp"
OUT_HEADER = ROOT / "src" / "ui" / "embedded_fonts.h"

FONTS = [
    ("kInterRegular", "Inter-Regular-Subset.ttf"),
    ("kInterBold", "Inter-Bold-Subset.ttf"),
    ("kJetBrainsMonoRegular", "JetBrainsMono-Regular-Subset.ttf"),
]

OUT_HEADER.write_text(
    """// Generated by third_party/fonts/embed_fonts.py; do not edit by hand.
#pragma once

#include <cstdint>
#include <span>

namespace krdbg::ui {

// The three embedded typefaces used by the canvas: Inter Regular, Inter Bold
// and JetBrains Mono Regular. All are SIL Open Font License 1.1; see
// third_party/fonts/.
struct EmbeddedFonts {
    std::span<const std::uint8_t> ui_regular;
    std::span<const std::uint8_t> ui_bold;
    std::span<const std::uint8_t> mono_regular;
};

EmbeddedFonts embedded_fonts();

} // namespace krdbg::ui
""",
    encoding="utf-8",
    newline="\n",
)

lines = [
    "// Generated by third_party/fonts/embed_fonts.py; do not edit by hand.",
    '#include "embedded_fonts.h"',
    "",
    "#include <array>",
    "",
    "namespace krdbg::ui {",
    "namespace {",
]
for name, filename in FONTS:
    data = (FONT_DIR / filename).read_bytes()
    lines.append(f"constexpr std::array<std::uint8_t, {len(data)}> {name} = {{")
    for i in range(0, len(data), 16):
        chunk = data[i : i + 16]
        lines.append("    " + ", ".join(f"0x{byte:02X}" for byte in chunk) + ",")
    lines.append("};")
    lines.append("")
lines.extend(
    [
        "} // namespace",
        "",
        "EmbeddedFonts embedded_fonts() {",
        "    return EmbeddedFonts{kInterRegular, kInterBold,",
        "                        kJetBrainsMonoRegular};",
        "}",
        "",
        "} // namespace krdbg::ui",
        "",
    ]
)
OUT_CPP.write_text("\n".join(lines), encoding="utf-8", newline="\n")
print(f"wrote {OUT_CPP} and {OUT_HEADER}")
